    { t: "mc", q: "Wann ist der Würfel gelöst?", o: ["Wenn alle Felder weiß sind", "Wenn man ihn zehnmal gedreht hat", "Wenn jede Seite nur noch eine Farbe hat"], a: 2, h: "bis jede Seite nur noch eine Farbe hat" },
    { t: "yn", q: "Wusste der Erfinder, dass sein Würfel so berühmt werden würde?", a: false, h: "ahnte er nicht" },
    { t: "yn", q: "Können auch Kinder lernen, den Würfel zu lösen?", a: true, h: "Mit etwas Übung lernen auch Kinder, ihn zu lösen." }
